      hu: ["1897-ben épült.", "Neoklasszicista stílus.", "1993 óta elnöki palota.", "2 hektáros kert.", "Bálteremmel rendelkezik.", "Nemzeti műemlék."],
      ro: ["Construit în 1897.", "Stil neoclasic.", "Reședință prezidențială din 1993.", "Grădină de 2 hectare.", "Salon de bal.", "Monument național."],
      en: ["Built in 1897.", "Neoclassical style.", "Presidential palace since 1993.", "2-hectare garden.", "Contains a ballroom.", "National heritage monument."],
